function GachaponGuideAnim:OnClickSkipHandler_()
    if not self.isControllable_ then return end

    if self._isOnlyShowSSR then
        return
    end

    -- 海外SSR自选卡池是十个ssr，所以需要一键跳到底
    if self._pool.poolType == GachaponConstants.PoolType.OverseaOptional then
        self:SkipToResult_()
        return
    end
    
    -- 当前只显示ssr
    self._isOnlyShowSSR = true

    -- 控制 tips 跳过
    if self:GetTips() then
        self:SetTips(false)
        CriWareUtils.StopById(self.takeOutBallSeName_)
    end

    -- 首先设置 跳过按钮和文字不可见
    local Image = CS.UnityEngine.UI.Image
    local TextComp = CS.UnityEngine.UI.Text
    ---@type UnityEngine.UI.Image
    local image =  self.btnSkip.gameObject:GetComponent(typeof(Image))
    if not isNull(image) then
        image.enabled = false
    end
    ---@type UnityEngine.UI.Text
    local text =  self.TextSkip.gameObject:GetComponent(typeof(TextComp))
    if not isNull(text) then
        text.enabled = false
    end

    if self._isShowSSRAnime then
        -- 控制 tips 跳过
        if self:GetShare() then
            self:SetShare(false)
        end
        -- 控制 timeline 跳过
        if self._isCanBeSkipped and self._isWaitForAction then
            self._isWaitForAction = false
            self._isActionSkipped = true
        end
        return
    end

    self:ShowSSR()
end

function GachaponGuideAnim:OnClicMaskkHandler_()
    if not self.isControllable_ then return end

    -- 控制 tips 跳过
    if self:GetTips() then
        self:SetTips(false)
        CriWareUtils.StopById(self.takeOutBallSeName_)
    end
    if self:GetShare() then
        self:SetShare(false)
    end

    -- 控制 timeline 跳过
    if self._isCanBeSkipped and self._isWaitForAction then
        self._isWaitForAction = false
        self._isActionSkipped = true
    end
end

function GachaponGuideAnim:SkipToResult_()
    if self._startCo ~= nil then
        CoStop(self._startCo)
        self._startCo = nil
    end
    local preLoadedTimelines = clone(self._loadedTimelines)
    for tlPath, _ in pairs(preLoadedTimelines)  do
        self:StopTimeline(tlPath)
    end
    CriWareUtils.StopById(GachaponConstants.GachaponSE.CallTen)
    CriWareUtils.StopById(GachaponConstants.GachaponSE.CallOne)
    CoStart(function()
        self.isControllable_ = false
        self:ShowResult()
    end)
end

function GachaponGuideAnim:ShowResult()
    local gachaponResultViewId = GachaponUtils.IsOverseaLightDarkType(self._pool.poolType) and Constants.UITypeIds.GachaponResultViewSpecial or Constants.UITypeIds.GachaponResultViewNew
    coroutine.yield(GachaponUtils.OpenDialogAction(gachaponResultViewId, {
        activityPoint = self._activityPoint,
        result        = self._tabResult,
        jumpIndex     = self._jumpIndex,
        topRare       = self._topRare,
        CallType      = self._callType,
        Pool          = self._pool,
        statistic     = self._statistic,
        isRookieCall  = self._isRookieCall,
        taskTipsNode  = self._taskTipsNode,
        responseData  = self._responseData,
    }, nil))

    URPCameraController.alwaysShowSceneRT = false
    self.controller:Close()
end

function GachaponGuideAnim:ShowSSR()
