        end
        CriWareUtils.StopById(GachaponConstants.GachaponSE.CallTen)
        CriWareUtils.StopById(GachaponConstants.GachaponSE.CallOne)

        --------------------------------------------------------------------------------------------------
        self:StartAnimPart2()
    end)
end

function GachaponGuideAnim:OnInitialize()
    return CoWaitDo(function()
        local param         = self.controller.Argument.parameters
        self._tabResult     = param.result
        self._activityPoint = param.activityPoint
        self._jumpIndex     = param.jumpIndex
        self._topRare       = param.topRare
        self._statistic     = param.statistic
        self._pool          = param.Pool
        self._callType      = param.CallType
        self._isRookieCall  = param.isRookieCall
        self._isLinkVideo   = param.linkVideo == true
        self._isSkipVideo   = true  -- 又说是里面不需要再播了 --param.skipVideo == true
        self._taskTipsNode  = param.taskTipsNode
        self._responseData  = param.responseData

        -- 播放前，需要先将场景状态 和 缓存对象恢复一下。因为可能会出现进入时场景元素被全关闭的状态。
        -- 复现流程是：先抽卡结束后进入抽卡结果界面，点击继续抽卡，提示道具不足，点击前往商城购买（这时跳转前往商城会让场景中的全部节点关闭）。
        -- 购买成功回到抽卡结果界面，点击继续抽卡，这时候场景中的场景节点、抽卡prefab缓存根节点，等节点都被关闭着，导致抽卡表现全程黑屏，所以这里需要做一次状态恢复。
        self:UpdateSceneStatus(true)
        self:UpdateMainSceneStatus(false)
        self:UpdateMainSceneLight(true)
        self:InitLayout()

        -- switch parent
        if isNotNull(self._taskTipsNode) then
            self._taskTipsNode.controller.transform:SetParent(self.controller.transform)
        end
    end)
end

function GachaponGuideAnim:OnFinalize()
    return CoWaitDo(function()
        if self._startCo ~= nil then
            CoStop(self._startCo)
            self._startCo = nil
        end
        if self._startCo2 ~= nil then
            CoStop(self._startCo2)
            self._startCo2 = nil
        end
        -- 先关闭掉RT
        URPCameraController.alwaysShowSceneRT = false
        -- CriWareUtils.StopById(GachaponConstants.GachaponSE.OpenDoor)

        -- local sceneSettingId = GachaponConstants.GachaponGuideAnimSceneDefine.SCENE_ID
        -- local sceneInstance  = GachaponShared:GetAppendedScene(sceneSettingId)
        -- sceneInstance:Disable()
        self:UpdateMainSceneStatus(true)
        self:UpdateMainSceneLight(true)

        -- CfUtils.SetActive(GachaponShared:GetLoadModelParentGo(), true)

        CfUtils.DialogClose(Constants.UITypeIds.GachaponResult)
        CfUtils.DialogClose(Constants.UITypeIds.CommonCardDisplayDialog)

        CfUtils.SetActive(URPCameraController.mainCamera, true)

        -- for sceneId, _ in pairs(self._loadedScenes or {}) do
        --     GachaponShared:UnloadScene(sceneId)
        -- end

        for tlPath, _ in pairs(self._loadedTimelines or {}) do
            self:StopTimeline(tlPath)
            local cullingMaskData = self.cullingMaskMap and self.cullingMaskMap[tlPath] or nil
            if cullingMaskData and cullingMaskData.camera then
                cullingMaskData.camera.cullingMask = cullingMaskData.origin
            end
            -- 大招timeline不做保留
            local isTimeline5 = string.find(tlPath, GachaponConstants.GachaponGuideAnimTLDefine.TIMELINE_5.MARKED) ~= nil
            if isTimeline5 then
                GachaponShared:DisposeSingle(tlPath)
            end
        end

        for objPath, _ in pairs(self._loadedObjects or {}) do
            -- GachaponShared:DisposeSingle(objPath)
            local prefabModel = GachaponShared:GetModel(objPath)
            -- 过滤掉资源类型的处理
            if isNotNull(prefabModel) and prefabModel.transform then
                if GachaponShared:GetLoadModelParentGo() then
                    prefabModel.transform:SetParent(GachaponShared:GetLoadModelParentGo().transform)
                end
                prefabModel.transform.localPosition = Vector3(0, 0, 0)
                prefabModel.transform.localRotation = Quaternion.Euler(0, 0, 0)
                CfUtils.SetActive(prefabModel, false)
            end
        end

        for rolePath, _ in pairs(self._loadedRoles or {}) do
            GachaponShared:DisposeSingle(rolePath)
        end
        for rolePath, _ in pairs(self._preloadedRoles or {}) do
            GachaponShared:DisposeLoaderSingle(rolePath)
        end

        -- if self._originalScene then
        --     SceneManager.SetActiveScene(self._originalScene)
        -- end
        xTry(function()
            if self.timeLineData then
                self:CloseTimelineByDefine(self.timeLineData.timelineDefine, self.timeLineData.trackBindList, self.timeLineData.trackmodelObjs, self.timeLineData.tlMarkerCallback)
                self.timeLineData = nil
            end
            if self.timeline3 then
                for i, gameObject in pairs(self.timeline3) do
                    GachaponShared:SetParentToGo(gameObject)
                end
                self.timeline3 = nil
            end

            local TIMELINE_3_DEFINE =  self.TIMELINE_3_DEFINE
            if TIMELINE_3_DEFINE then
                local timelinePrafeb = GachaponShared:GetModel(TIMELINE_3_DEFINE.PREFAB)
                if not isNull(timelinePrafeb) then
                    -- 直接销毁 TIMELINE_3_DEFINE
                    GachaponShared:DisposeEnterAnim({TIMELINE_3_DEFINE.PREFAB})
                end
            end
        end)

        self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
        -- 关闭界面前 alwaysShowSceneRT 必为false
    end)
end

