function GachaponGuideAnim:PreloadAssets()
    local isAllGoods  = true
    local preloadDict = {}
    local isMultiType = checkInt(self._callType) == GachaponConstants.CallType.Ten  -- 1 单抽，2 十连

    -- load hand model
    -- local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent) or {}
    -- local isFemalePlayer  = playerComponent.playerDojo and (checkInt(playerComponent.playerDojo.gender) == Constants.PLAYER_GENDER.FEMALE)
    -- local handPrefabPath  = string.format(GachaponConstants.GachaponGuideAnimHandPath, isFemalePlayer and 'f' or 'm')
    -- preloadDict[handPrefabPath] = true

    -- load scene model
    -- local scenePrefabPath = GachaponConstants.GachaponGuideAnimScenePath
    -- preloadDict[scenePrefabPath] = true
    
    -- load ball model
    local ballPrefabPath = GachaponConstants.GachaponGuideAnimBallTypePath[checkInt(self._pool.poolType)]
    if not ballPrefabPath then
        ballPrefabPath = GachaponConstants.GachaponGuideAnimBallPath
    end
    preloadDict[ballPrefabPath] = true
    
    -- load bead models
    if isMultiType then
        local beadPathMap = GachaponConstants.GachaponGuideAnimBeadPath
        if GachaponUtils.IsOverseaLightDarkType(self._pool.poolType) then
            beadPathMap = GachaponConstants.GachaponGuideAnimLightDarkBeadPath
            preloadDict[GachaponConstants.GachaponGuideAnimLightDarkGoodsBeadPath] = true
        end
        for _, beadPrefabPath in pairs(beadPathMap) do
            preloadDict[beadPrefabPath] = true
        end
    end

    -- timelien part1
    -- local TIMELINE_1_DEFINE = GachaponConstants.GachaponGuideAnimTLDefine.TIMELINE_1
    -- preloadDict[TIMELINE_1_DEFINE.PREFAB] = true

    -- -- timelien part2
    -- local TIMELINE_2_DEFINE = GachaponConstants.GachaponGuideAnimTLDefine.TIMELINE_2
    -- preloadDict[TIMELINE_2_DEFINE.PREFAB] = true

    -- -- timelien part2 loop
    -- local TIMELINE_2_LOOP_DEFINE = GachaponConstants.GachaponGuideAnimTLDefine.TIMELINE_2_LOOP
    -- preloadDict[TIMELINE_2_LOOP_DEFINE.PREFAB] = true

    ---@type table<integer, table<string, boolean>>
    local catAnimClipMapDict = {}
    self._preloadedRoles = {}

    -- timelien part3
    local TIMELINE_3_DEFINE = isMultiType and GachaponConstants.GachaponGuideAnimTLDefine.TIMELINE_3_2 or GachaponConstants.GachaponGuideAnimTLDefine.TIMELINE_3_1
    if GachaponUtils.IsOverseaLightDarkType(self._pool.poolType) and TIMELINE_3_DEFINE.PREFAB_L ~= nil then
        preloadDict[TIMELINE_3_DEFINE.PREFAB_L] = true
    else
        preloadDict[TIMELINE_3_DEFINE.PREFAB] = true
    end
    
    for resultIndex, resultData in ipairs(self._displayResult or {}) do
        ---@type CardVo | nil
        local eachResultCardVo  = GachaponUtils.IsCardGoods(resultData.goodsId) and CardConfMgr:GetInstance():GetCardByRefId(resultData.goodsId) or nil
        local tl5RolePrefabPath = eachResultCardVo ~= nil and string.format(GachaponConstants.GachaponGuideAnimTLDefine.TIMELINE_5.PREFAB, eachResultCardVo.roleId) or nil
        local isExistTimeline5  = eachResultCardVo ~= nil and eachResultCardVo.animation and CfUtils.IsBundleResourceExist(tl5RolePrefabPath)
        local tlRoleRateDefine  = self._tlRareDefines[resultIndex]

        -- load cat model
        local catPrefabPath = GachaponUtils.GetCatPrefabPath(eachResultCardVo)
        preloadDict[catPrefabPath] = true

        -- load role model
        if eachResultCardVo then
            local rolePrefabPath = string.format(GachaponConstants.RoleLobbyResPath, eachResultCardVo.cultivateRes)
            preloadDict[rolePrefabPath] = true
            self._preloadedRoles[rolePrefabPath] = true
            isAllGoods = false
        end
        
        -- timeline part4
        local tl4PlaceTrackList = {}
        local tl4PlaceModelList = {}
        local TIMELINE_4_DEFINE = (isExistTimeline5 and tlRoleRateDefine.tl0Define) and tlRoleRateDefine.tl0Define or tlRoleRateDefine.tlDefine
        if GachaponUtils.IsOverseaLightDarkType(self._pool.poolType) and TIMELINE_4_DEFINE.PREFAB_L ~= nil then
            preloadDict[TIMELINE_4_DEFINE.PREFAB_L] = true
        else
            preloadDict[TIMELINE_4_DEFINE.PREFAB] = true
        end

        -- timeline part5
        if isExistTimeline5 then
            local TIMELINE_5_DEFINE  = clone(GachaponConstants.GachaponGuideAnimTLDefine.TIMELINE_5)
            TIMELINE_5_DEFINE.PREFAB = tl5RolePrefabPath
            preloadDict[TIMELINE_5_DEFINE.PREFAB] = true
        end

        -- cat animClip
        if eachResultCardVo then
            local characterCatId = GachaponUtils.GetCharacterCatId(eachResultCardVo)
            if not catAnimClipMapDict[characterCatId] then
                local catAnimClipMap = {}
                for _, clipType in ipairs(TIMELINE_3_DEFINE.CAT_CLIPS) do
                    catAnimClipMap[clipType] = true
                end
                for _, clipType in ipairs(TIMELINE_4_DEFINE.CAT_CLIPS) do
                    catAnimClipMap[clipType] = true
                end
                for clipType, _ in pairs(catAnimClipMap) do
                    local catAnimClipPath = GachaponUtils.GetCatAnimClipPath(eachResultCardVo, clipType)
                    preloadDict[catAnimClipPath] = true
                end
                catAnimClipMapDict[characterCatId] = catAnimClipMap
            end
        end
    end

    if isAllGoods then
        -- timeline goods
        local TIMELINE_GOODS_DEFINE = GachaponConstants.GachaponGuideAnimTLDefine.TIMELINE_GOODS
        preloadDict[TIMELINE_GOODS_DEFINE.PREFAB] = true
    else
        -- timeline part6
        local TIMELINE_6_DEFINE = GachaponConstants.GachaponGuideAnimTLDefine.TIMELINE_6
        preloadDict[TIMELINE_6_DEFINE.PREFAB] = true
    end

    -- to preload assets
    logt(preloadDict, '>>> preloadDict <<<')
    for prefabPath, _ in pairs(preloadDict) do
        GachaponShared:LoadModelAsync(prefabPath)
    end
end

function GachaponGuideAnim:StartAnim()
    self._displayResult   = {}
    self._tlRareDefines   = {}
    -- self._loadedScenes    = {}
    self._loadedObjects   = {}
    self._loadedRoles     = {}
    self._loadedTimelines = {}
    -- self._originalScene   = SceneManager.GetActiveScene()
    self._isCanBeSkipped  = false
    self._isWaitForAction = false
    self._isActionSkipped = false
    self.isControllable_  = false

    local isMultiType = checkInt(self._callType) == GachaponConstants.CallType.Ten  -- 1 单抽，2 十连

    -- sort displayResult
    local topRareIndex  = 1--self:GetTopRareIndex() 没玄学了
    ---@type GachaponGuideAnimRateDefine[]
    local tlRareDefines = {}
    local displayResult = {}
    local firstCardIndex = 0
    for index, result in ipairs(self._tabResult) do
        local cardVo     = GachaponUtils.IsCardGoods(result.goodsId) and CardConfMgr:GetInstance():GetCardByRefId(result.goodsId) or nil
        local rateDefine = self:GetTimelineRateDefineByCardRare(cardVo and cardVo.rare or Constants.RareType.R)  -- 道具先用R品质定义占位，因为是list要按照顺序调用
        if cardVo ~= nil and firstCardIndex == 0 then
            firstCardIndex = index
        end
        --if topRareIndex == index then
        --    table.insert(displayResult, 1, result) -- to top
        --    table.insert(tlRareDefines, 1, rateDefine) -- to top
        --else
        --    table.insert(displayResult, result)  -- push list
        --    table.insert(tlRareDefines, rateDefine) -- to top
        --end
        table.insert(displayResult, result)  -- push list
        table.insert(tlRareDefines, rateDefine) -- to top
    end
    self._displayResult = displayResult
    self._tlRareDefines = tlRareDefines

    -- 如果结果的第一个不是卡，那么需要找到第一个卡的位置，交换到结果的第一个位置。
    -- 不然会出现当第一个是道具表现：天上十个球转动完，第一个球砸向地面后（道具会跳过起跳表现），一直跳过表现直到突然变成一只猫，原地起跳起来
    if firstCardIndex > 1 then
        local result     = table.remove(self._displayResult, firstCardIndex)
        local rateDefine = table.remove(self._tlRareDefines, firstCardIndex)
        table.insert(self._displayResult, 1, result)
        table.insert(self._tlRareDefines, 1, rateDefine)
    end

    -- enable blocker
    local blockerName = "GachaponGuideAnim"
    CfUtils.ConditionAppend(blockerName)
    self:SetTestLabelText('StartAnim')

    self._startCo = CoStart(function()
