        GachaponShared:SetTempContent(nil)


        ------------------------------------------------- [part_3：抛球给猫]

        -- load cat model
        local topRateResult = checkTable(displayResult[topRareIndex])
        local topRareCardVo = GachaponUtils.IsCardGoods(topRateResult.goodsId) and CardConfMgr:GetInstance():GetCardByRefId(topRateResult.goodsId) or nil
        local topTlBaseRare = topRareCardVo and tlRareDefines[topRareIndex].baseRare or Constants.RareType.SR  -- 道具特效做在了SR轨上了，所以这里写死先
        local catPrefabPath = GachaponUtils.GetCatPrefabPath(topRareCardVo)
        self:LoadPrefabModel(catPrefabPath, true)

        -- init cat model
        local catPrefab = GachaponShared:GetModel(catPrefabPath)
        catPrefab.transform.localPosition = Vector3(0, 0, 0)
        catPrefab.transform.localRotation = Quaternion.Euler(0, 0, 0)

        -- load bead models
        local beadPrefabPathMap = {}
        if isMultiType then
            for resultIndex, resultData in ipairs(displayResult) do
                local beadPrefabPath = self:GetBeadPrefabPath(tlRareDefines[resultIndex], displayResult[resultIndex])
                if beadPrefabPath and not beadPrefabPathMap[beadPrefabPath] then
                    self:LoadPrefabModel(beadPrefabPath)
                    beadPrefabPathMap[beadPrefabPath] = true
                end
            end
        end

        -- play timeline part3
        local tl3PlaceTrackList = {}
        local tl3PlaceModelList = {}
        local tl3MarkerCallback = nil
        local TIMELINE_3_DEFINE = clone(isMultiType and GachaponConstants.GachaponGuideAnimTLDefine.TIMELINE_3_2 or GachaponConstants.GachaponGuideAnimTLDefine.TIMELINE_3_1)
        if GachaponUtils.IsOverseaLightDarkType(self._pool.poolType) and TIMELINE_3_DEFINE.PREFAB_L ~= nil then
            TIMELINE_3_DEFINE.PREFAB = TIMELINE_3_DEFINE.PREFAB_L
        end
        self.TIMELINE_3_DEFINE = TIMELINE_3_DEFINE

        -- load cat animClips
        for _, clipType in ipairs(TIMELINE_3_DEFINE.CAT_CLIPS) do
            local catAnimClipPath = GachaponUtils.GetCatAnimClipPath(topRareCardVo, clipType)
            if catAnimClipPath then
                self:LoadPrefabModel(catAnimClipPath)
            end
        end

        local isPlayTl3Sounds  = false
        self:SetTestLabelText(TIMELINE_3_DEFINE.NAME .. '_relay')
        self:LoadAndPlayTimelineByDefine(TIMELINE_3_DEFINE, false,
