            function()
                self:SetTestLabelText(TIMELINE_3_DEFINE.NAME .. '_loaded')
                -- self:CloseTimelineByDefine(TIMELINE_2_LOOP_DEFINE, tl2LooopPlaceTrackList, tl2LooopPlaceModelList)
                -- self:UpdateSceneStatus(sceneInstance, true)
                CfUtils.SetActive(self.frontBlock, false)
                GachaponShared:SetTempContent(nil)
                -- preload assets
                self:PreloadAssets()
            end,
            -- init callback
            function(director, tlPath)
                self:SetTestLabelText(TIMELINE_3_DEFINE.NAME .. '_initial')
                tl3MarkerCallback  = GachaponUtils.AppendTimelineCustomNotify(director, Bind(self, self.OnTimelineMarkerNotifyHandler_, tlPath))
                tl3PlaceTrackList[1], tl3PlaceModelList[1] = self:PlaceModelToTimelineTrack(director, catPrefabPath,  TIMELINE_3_DEFINE.PREFAB, TIMELINE_3_DEFINE.CAT_PLACE, topRareCardVo and TIMELINE_3_DEFINE.CAT_TRACK or TIMELINE_3_DEFINE.GOODS_TRACK)
                -- CfUtils.SetActive(tl3PlaceModelList[1].gameObject ,false)
                -- CoStart(function()
                --     CoYield()
                --     CoYield()
                    CfUtils.SetActive(tl3PlaceModelList[1].gameObject ,true)
                -- end)
                tl3PlaceTrackList[2], tl3PlaceModelList[2] = self:PlaceModelToTimelineTrack(director, ballPrefabPath, TIMELINE_3_DEFINE.PREFAB, TIMELINE_3_DEFINE.BALL_PLACE, TIMELINE_3_DEFINE.BALL_TRACK)
                -- tl3PlaceTrackList[3], tl3PlaceModelList[3] = self:PlaceModelToTimelineTrack(director, scenePrefabPath, TIMELINE_3_DEFINE.PREFAB, TIMELINE_3_DEFINE.SCENE_PLACE, TIMELINE_3_DEFINE.SCENE_TRACK)
                -- tl3PlaceTrackList[4], tl3PlaceModelList[4] = self:PlaceModelToTimelineTrack(director, handPrefabPath, TIMELINE_3_DEFINE.PREFAB, TIMELINE_3_DEFINE.HAND_PLACE, TIMELINE_3_DEFINE.HAND_TRACK)
                self.timeline3[catPrefabPath] = tl3PlaceModelList[1]
                self.timeline3[ballPrefabPath] = tl3PlaceModelList[2]
                -- self.timeline3[scenePrefabPath] = tl3PlaceModelList[3]
                -- self.timeline3[handPrefabPath] = tl3PlaceModelList[4]
                self:SetCurrentTimeLineData(TIMELINE_3_DEFINE, tl3PlaceTrackList, tl3PlaceModelList, tl3MarkerCallback)
                if isMultiType then
                    for resultIndex, resultData in ipairs(displayResult) do
                        local beadPlaceName = TIMELINE_3_DEFINE['BEAD_PLACE_' .. resultIndex]
                        if beadPlaceName then
                            local beadPrefabPath = self:GetBeadPrefabPath(tlRareDefines[resultIndex], displayResult[resultIndex])
                            local duplicateBead  = CfUtils.InstantiateGo(GachaponShared:GetModel(beadPrefabPath))
                            local placeTrack, placeModel = self:PlaceModelToTimelineTrack(director, duplicateBead, TIMELINE_3_DEFINE.PREFAB, beadPlaceName)
                            table.insert(tl3PlaceTrackList, placeTrack)
                            table.insert(tl3PlaceModelList, placeModel)
                        end
                    end
                end
                -- 品质特效开关
                for _, trackDefines in pairs(TIMELINE_3_DEFINE.RARE_TRACKS) do
                    for trackRare, trackName in pairs(trackDefines) do
                        GachaponUtils.SetRootTrackMute(director, trackName, topTlBaseRare ~= trackRare)
                    end
                end
                -- 因为loop会晃动球，导致球的坐标一直在变化，所以为了正确衔接part3，所以记录了球在part2时的正确位置
                local modelPrefabObj = self:InitPrefabModel(ballPrefabPath)
                modelPrefabObj.transform.localPosition = ballLocalPosition
                modelPrefabObj.transform.localRotation = balllocalRotation

                local throwOutBallSeName = GachaponConstants.GachaponSE.ThrowOutBallMap[checkInt(self._pool.poolType)] or GachaponConstants.GachaponSE.ThrowOutBall
                CriWareUtils.PlaySeById(throwOutBallSeName)

                --- 替换猫动画
                if topRareCardVo then
                    ---@param clip UnityEngine.Timeline.TimelineClip
                    GachaponUtils.EachTimelineAnimationClips(director, TIMELINE_3_DEFINE.CAT_TRACK, function(clip)
                        ---@type UnityEngine.Timeline.AnimationPlayableAsset
                        local clipAsset = clip.asset
                        local nameKeys  = string.split(tostring(clip.displayName), '_')
                        local clipType  = tostring(nameKeys[1])
                        local clipPath  = GachaponUtils.GetCatAnimClipPath(topRareCardVo, clipType)
                        if clipPath then
                            clipAsset.clip  = GachaponShared:GetModel(clipPath)
                        end
                    end)
                end
            end,
            -- finish callback
            function(director)
                self:SetTestLabelText(TIMELINE_3_DEFINE.NAME .. '_finish')
                for _, trackDefines in pairs(TIMELINE_3_DEFINE.RARE_TRACKS) do
                    for trackRare, trackName in pairs(trackDefines) do
                        GachaponUtils.SetRootTrackMute(director, trackName, true)
                    end
                end
                -- if not CardUtils.IsMonsterCard(topRareCardVo.roleId) then
                    CriWareUtils.PlaySeById(GachaponConstants.GachaponSE.CatKeepDown)
                -- end
            end,
            -- update callback
            function(time, duration)
                self:SetTestLabelText(TIMELINE_3_DEFINE.NAME .. string.format('_%0.3f/%0.3f', time, duration))
                if time >= 3 and not isPlayTl3Sounds then
                    if isMultiType then
                        CriWareUtils.PlaySeById(GachaponConstants.GachaponSE.CallTen)
                    else
                        CriWareUtils.PlaySeById(GachaponConstants.GachaponSE.CallOne)
                    end
                    isPlayTl3Sounds = true
                end
            end
        )

        -- while true do
        --     CoYield()
        -- end

        --------------------------------------------------------------------------------------------------
        self:StartAnimPart2(TIMELINE_3_DEFINE, tl3PlaceTrackList, tl3PlaceModelList, tl3MarkerCallback)
    end)
end
function GachaponGuideAnim:StartAnimPart2(TIMELINE_3_DEFINE, tl3PlaceTrackList, tl3PlaceModelList, tl3MarkerCallback)
        local lastTimelineDefine = TIMELINE_3_DEFINE
        local lastPlaceTrackList = tl3PlaceTrackList or {}
        local lastPlaceModelList = tl3PlaceModelList or {}
        local lastMarkerCallback = tl3MarkerCallback
        local isSkipToShowResult = self._isActionSkipped
        local isShowingCardInfo  = false
        local isWaitingShowInfo  = false

        local showCardInfoDialog = function(gachaponData, haveTimeline5)
            if self._isShowSSRAnime then return end
            isShowingCardInfo = true
            if not haveTimeline5 then
                CriWareUtils.PlaySeById(GachaponConstants.GachaponSE.TurnBackRole)
            end
            coroutine.yield(GachaponUtils.OpenDialogAction(Constants.UITypeIds.GachaponResult, {gachaponData = gachaponData, isHaveLight = haveTimeline5}, nil))
        end

        local showCardDisplayDialog = function(gachaponData)
            if not self._isShowSSRAnime then return end
            isShowingCardInfo = true
            isWaitingShowInfo = true
            coroutine.yield(GachaponUtils.OpenDialogAction(Constants.UITypeIds.CommonCardDisplayDialog, {
                cardInfo   = { {isNew = isSet(gachaponData, "playerCard"), goodsId = gachaponData.goodsId} }, 
                isHideSkip = self._isOnlyShowSSR,
                finishCb   = function()
                    isWaitingShowInfo = false
                    -- if self._isOnlyShowSSR then
                    --     self:OnClicMaskkHandler_()
                    -- end
                end,
                onCloseCb  = function()
                    self:OnClicMaskkHandler_()
                end,
                onSkipCb   = function()
                    isWaitingShowInfo = false
                    self:OnClickSkipHandler_()
                end
            }, nil))
        end

    local isAllGoods = true
    for resultIndex, resultData in ipairs(self._displayResult) do
        local eachResultCardVo = GachaponUtils.IsCardGoods(resultData.goodsId) and CardConfMgr:GetInstance():GetCardByRefId(resultData.goodsId) or nil
        repeat
            if eachResultCardVo == nil then
                break
            end
            isAllGoods = false

            -- 非播SSR模式：每个结果都要播放
            -- 只播SSR模式：只有品质SSR，并且要基于上一次播放的位置后面继续（因为可能刚刚播放完一个SSR，然后点跳过后，需要从这个位置后面遍历）
            if (not self._isOnlyShowSSR) or (self._isOnlyShowSSR and eachResultCardVo.rare == Constants.RareType.SSR and resultIndex > self._currentIndex) then
                self._currentIndex   = resultIndex
                self._isShowSSRAnime = eachResultCardVo.rare == Constants.RareType.SSR

                ------------------------------------------------- [part_4：跳起变身]
                local tlRoleRateDefine  = self._tlRareDefines[resultIndex]
                local tl5RolePrefabPath = string.format(GachaponConstants.GachaponGuideAnimTLDefine.TIMELINE_5.PREFAB, eachResultCardVo.roleId)
                local tl5RolePrefabName = string.format(GachaponConstants.GachaponGuideAnimTLDefine.TIMELINE_5.NAME, eachResultCardVo.roleId)
                local isExistTimeline5  = eachResultCardVo.animation and CfUtils.IsBundleResourceExist(tl5RolePrefabPath)

                -- load cat model
                local catPrefabPath = GachaponUtils.GetCatPrefabPath(eachResultCardVo)
                if isNull(GachaponShared:GetModel(catPrefabPath)) then
                    self:LoadPrefabModel(catPrefabPath, true)
                end

                -- load role model
                local rolePrefabPath = string.format(GachaponConstants.RoleLobbyResPath, eachResultCardVo.cultivateRes)
                local rolePrefabLoad = false
                local rolePrefabInit = function()
                    if isNull(GachaponShared:GetModel(rolePrefabPath)) then
                        self:LoadPrefabModel(rolePrefabPath, isExistTimeline5)
                    end
                    self._loadedRoles[rolePrefabPath] = true
                    rolePrefabLoad = true
                end

                -- play timeline part4
                local tl4PlaceTrackList = {}
                local tl4PlaceModelList = {}
                local tl4MarkerCallback = nil
                local TIMELINE_4_DEFINE = clone((isExistTimeline5 and tlRoleRateDefine.tl0Define) and tlRoleRateDefine.tl0Define or tlRoleRateDefine.tlDefine)
                if GachaponUtils.IsOverseaLightDarkType(self._pool.poolType) and TIMELINE_4_DEFINE.PREFAB_L ~= nil then
                    TIMELINE_4_DEFINE.PREFAB = TIMELINE_4_DEFINE.PREFAB_L
                end

                -- load cat animClips
                for _, clipType in ipairs(TIMELINE_4_DEFINE.CAT_CLIPS) do
                    local catAnimClipPath = GachaponUtils.GetCatAnimClipPath(eachResultCardVo, clipType)
                    if catAnimClipPath then
                        self:LoadPrefabModel(catAnimClipPath)
                    end
                end
                
                local timeline4LoadedCb = function()
                    --[[
                        当前上个timeLine 不马上关闭的条件
                        1.resultIndex > 1
                        2. 当前不是SSR卡
                        3. 不存在timeline5
                    ]]
                    -- self:UpdateSceneStatus(sceneInstance, true)
                    self:UpdateMainSceneLight(true)

                    CfUtils.DialogClose(Constants.UITypeIds.GachaponResult)
                    CfUtils.DialogClose(Constants.UITypeIds.CommonCardDisplayDialog)

                    if (not isExistTimeline5) and (resultIndex > 1 and eachResultCardVo.rare ~= Constants.RareType.SSR)  then
                    else
                        -- 如果是SSR 并且SSR  resultIndex 大于 1 就截屏
                        if resultIndex > 1 and eachResultCardVo.rare == Constants.RareType.SSR then
                            URPCameraController.alwaysShowSceneRT = true
                        end
                    end
                    self:CloseTimelineByDefine(lastTimelineDefine, lastPlaceTrackList, lastPlaceModelList, lastMarkerCallback)
                end

                -- 1，抽卡动画中，首张卡需播放猫起跳过程，后续只有在抽到SSR的时候，才播放猫起跳；
                -- 2，抽卡动画中，抽到R卡时，自动播放下一张，抽到SR与SSR时，定格后，需玩家手动点击后，再播放下一张卡牌；
                if  (resultIndex > 1 and eachResultCardVo.rare ~= Constants.RareType.SSR) then
                    isSkipToShowResult = true
                else
                    isSkipToShowResult = self._isActionSkipped
                end

                -- skip from part_3
                if isSkipToShowResult then
                    -- timeline4LoadedCb()
                else
                    self:SetTestLabelText(TIMELINE_4_DEFINE.NAME .. '_relay')
                    self:LoadAndPlayTimelineByDefine(TIMELINE_4_DEFINE, false,
                        -- loaded callback
                        function()
                            self:SetTestLabelText(TIMELINE_4_DEFINE.NAME .. '_loaded')
                            timeline4LoadedCb()
                        end,
                        -- init callback
                        function(director, tlPath)
                            URPCameraController.alwaysShowSceneRT = false
                            self:SetTestLabelText(TIMELINE_4_DEFINE.NAME .. '_initial')
                            tl4MarkerCallback   = GachaponUtils.AppendTimelineCustomNotify(director, Bind(self, self.OnTimelineMarkerNotifyHandler_, tlPath))
                            local isMonsterCard = CardUtils.IsMonsterCard(eachResultCardVo.roleId)
                            tl4PlaceTrackList[1], tl4PlaceModelList[1] = self:PlaceModelToTimelineTrack(director, catPrefabPath, TIMELINE_4_DEFINE.PREFAB, TIMELINE_4_DEFINE.CAT_PLACE, TIMELINE_4_DEFINE.CAT_TRACK)
                            -- if TIMELINE_4_DEFINE.SCENE_PLACE then
                            --     tl4PlaceTrackList[2], tl4PlaceModelList[2] = self:PlaceModelToTimelineTrack(director, scenePrefabPath, TIMELINE_4_DEFINE.PREFAB, TIMELINE_4_DEFINE.SCENE_PLACE, TIMELINE_4_DEFINE.SCENE_TRACK)
                            -- end
                            -- if not isExistTimeline5 then
                            --     tl4PlaceTrackList[2], tl4PlaceModelList[2] = self:PlaceModelToTimelineTrack(director, rolePrefabPath, TIMELINE_4_DEFINE.PREFAB, TIMELINE_4_DEFINE.ROLE_PLACE)
                            -- end
                            self:SetCurrentTimeLineData(TIMELINE_4_DEFINE, tl4PlaceTrackList, tl4PlaceModelList, tl4MarkerCallback)

                            --- 替换猫动画
                            ---@param clip UnityEngine.Timeline.TimelineClip
                            GachaponUtils.EachTimelineAnimationClips(director, TIMELINE_4_DEFINE.CAT_TRACK, function(clip)
                                ---@type UnityEngine.Timeline.AnimationPlayableAsset
                                local clipAsset = clip.asset
                                local nameKeys  = string.split(tostring(clip.displayName), '_')
                                local clipType  = tostring(nameKeys[1])
                                local clipPath  = GachaponUtils.GetCatAnimClipPath(eachResultCardVo, clipType)
                                if clipPath then
                                    clipAsset.clip  = GachaponShared:GetModel(clipPath)
                                end
                            end)

                            -- if not isMonsterCard then
                                if eachResultCardVo.rare == Constants.RareType.SSR then
                                    CriWareUtils.PlaySeById(GachaponConstants.GachaponSE.CatJumpSSR)
                                elseif eachResultCardVo.rare == Constants.RareType.SR then
                                    CriWareUtils.PlaySeById(GachaponConstants.GachaponSE.CatJumpSR)
                                elseif eachResultCardVo.rare == Constants.RareType.R then
                                    CriWareUtils.PlaySeById(GachaponConstants.GachaponSE.CatJumpR)
                                end
                            -- end
                        end,
                        -- finish callback
                        function(director)
                            self:SetTestLabelText(TIMELINE_4_DEFINE.NAME .. '_finish')
                            URPCameraController.alwaysShowSceneRT = true
                            if isExistTimeline5 then return end
                            if not isShowingCardInfo then
                                showCardInfoDialog(resultData)
                                showCardDisplayDialog(resultData)
                            end
                        end,
                        -- update callback
                        function(time, duration, director)
                            self:SetTestLabelText(TIMELINE_4_DEFINE.NAME .. string.format('_%0.3f/%0.3f', time, duration))
                            if isExistTimeline5 then return end
                            if not isShowingCardInfo and duration - time <= CARD_INFO_PRE_SHOW_TIME then
                                showCardInfoDialog(resultData)
                            end
                            if self._isCanBeSkipped and duration - time <= TIMELINE_4_BLOCK_SKIP_TIME then
                                self._isCanBeSkipped = false
                            end
                            if not rolePrefabLoad and time >= 0.5 then
                                rolePrefabInit()
                                local tlPlaceIndex = #tl4PlaceTrackList + 1
                                tl4PlaceTrackList[tlPlaceIndex], tl4PlaceModelList[tlPlaceIndex] = self:PlaceModelToTimelineTrack(director, rolePrefabPath, TIMELINE_4_DEFINE.PREFAB, TIMELINE_4_DEFINE.ROLE_PLACE)
                            end
                        end
                    )
                end

                ------------------------------------------------- [part_5：大招出场表现]
                if isExistTimeline5 then

                    -- load role model
                    if not rolePrefabLoad then
                        rolePrefabInit()
                    end

                    -- play timeline part5
                    local tl5PlaceModelList  = {}
                    local tl5PlaceTrackList  = {}
                    local tl5MarkerCallback  = nil
                    local TIMELINE_5_DEFINE  = clone(GachaponConstants.GachaponGuideAnimTLDefine.TIMELINE_5)
                    TIMELINE_5_DEFINE.PREFAB = tl5RolePrefabPath
                    TIMELINE_5_DEFINE.NAME   = tl5RolePrefabName
                    self:SetTestLabelText(TIMELINE_5_DEFINE.NAME .. '_relay')
                    self:LoadAndPlayTimelineByDefine(TIMELINE_5_DEFINE, false,
                        -- loaded callback
                        function()
                            URPCameraController.alwaysShowSceneRT = false
                            self:SetTestLabelText(TIMELINE_5_DEFINE.NAME .. '_loaded')
                            self:CloseTimelineByDefine(TIMELINE_4_DEFINE, tl4PlaceTrackList, tl4PlaceModelList, tl4MarkerCallback)
                            timeline4LoadedCb()

                            -- self:UpdateSceneStatus(sceneInstance, false)

                            -- 大招自带灯光，所以播放part5时，临时关闭场景灯光
                            self:UpdateMainSceneLight(false)
                        end,
                        -- init callback
                        function(director, tlPath)
                            self:SetTestLabelText(TIMELINE_5_DEFINE.NAME .. '_initial')
                            tl5MarkerCallback = GachaponUtils.AppendTimelineCustomNotify(director, Bind(self, self.OnTimelineMarkerNotifyHandler_, tlPath))
                            tl5PlaceTrackList[1], tl5PlaceModelList[1] = self:PlaceModelToTimelineTrack(director, rolePrefabPath, TIMELINE_5_DEFINE.PREFAB, TIMELINE_5_DEFINE.ROLE_PLACE, TIMELINE_5_DEFINE.ROLE_TRACK)
                            self:SetCurrentTimeLineData(TIMELINE_5_DEFINE, tl5PlaceTrackList, tl5PlaceModelList, tl5MarkerCallback)

                            -- 手动关闭tl5中的主界面场景mask，不用考虑还原，因为tl5不显示场景
                            self:UpdateTimelineCameraCullingMask(TIMELINE_5_DEFINE.PREFAB, false)
                            if not string.isEmpty(eachResultCardVo.cueName) then
                                CriWareUtils.PlaySeById(eachResultCardVo.cueName)
                            end
                        end,
                        -- finish callback
                        function(director)
                            self:SetTestLabelText(TIMELINE_5_DEFINE.NAME .. '_finish')
                            if not isShowingCardInfo then
                                showCardInfoDialog(resultData)
                                showCardDisplayDialog(resultData)
                            end
                        end,
                        -- update callback
                        function(time, duration)
                            self:SetTestLabelText(TIMELINE_5_DEFINE.NAME .. string.format('_%0.3f/%0.3f', time, duration))
                            if not isShowingCardInfo then
                                if duration - time <= CARD_INFO_PRE_SHOW_TIME then
                                    showCardInfoDialog(resultData, true)
                                end
                                if duration - time <= CARD_DISPLAY_PRE_SHOW_TIME then
                                    showCardDisplayDialog(resultData)
                                end
                            end
                        end
                    )

                    lastTimelineDefine = TIMELINE_5_DEFINE
                    lastPlaceTrackList = tl5PlaceTrackList
                    lastPlaceModelList = tl5PlaceModelList
                    lastMarkerCallback = tl5MarkerCallback

                    if Constants.MODULE_SWITCH.SHARE then
                        Events.Broadcast(Constants.EventNames.GACHAPON_ANIM_RESULT_SHARE_ENABLE)
                    else
                        Events.Broadcast(Constants.EventNames.GACHAPON_ANIM_RESULT_CLOSE_ENABLE)
                    end

                    self:SetShare(true)

                    while self:GetShare() do
                        coroutine.yield()
                    end


                ------------------------------------------------- [part_6：站立出场表现]
                else
                    if isSkipToShowResult then

                        -- load role model
                        if not rolePrefabLoad then
                            rolePrefabInit()
                        end

                        -- play timeline part6
                        local tl6PlaceModelList = {}
                        local tl6PlaceTrackList = {}
                        local tl6MarkerCallback = nil
                        local TIMELINE_6_DEFINE = GachaponConstants.GachaponGuideAnimTLDefine.TIMELINE_6
                        self:SetTestLabelText(TIMELINE_6_DEFINE.NAME .. '_relay')
                        self:LoadAndPlayTimelineByDefine(TIMELINE_6_DEFINE, false,
                            -- loaded callback
                            function()
                                self:SetTestLabelText(TIMELINE_6_DEFINE.NAME .. '_loaded')
                                self:CloseTimelineByDefine(TIMELINE_4_DEFINE, tl4PlaceTrackList, tl4PlaceModelList, tl4MarkerCallback)
                                --[[
                                    1. 如果上一个 lastTimelineDefine 为 TIMELINE_6_DEFINE, 不销毁timeline 对象 ， 只隐藏gameobject 队形
                                ]]
                                if lastTimelineDefine == TIMELINE_6_DEFINE then
                                    self:CloseRolePrefabTimeLineByDefine(lastTimelineDefine,lastPlaceTrackList,lastPlaceModelList,lastMarkerCallback)
                                else
                                    self:CloseTimelineByDefine(lastTimelineDefine, lastPlaceTrackList, lastPlaceModelList, lastMarkerCallback)
                                end
                                CfUtils.DialogClose(Constants.UITypeIds.GachaponResult)
                                CfUtils.DialogClose(Constants.UITypeIds.CommonCardDisplayDialog)

                                -- self:UpdateSceneStatus(sceneInstance, true)
                                self:UpdateMainSceneLight(true)
                            end,
                            -- init callback
                            function(director, tlPath)
                                URPCameraController.alwaysShowSceneRT = false
                                self:SetTestLabelText(TIMELINE_6_DEFINE.NAME .. '_initial')

                                tl6MarkerCallback = GachaponUtils.AppendTimelineCustomNotify(director, Bind(self, self.OnTimelineMarkerNotifyHandler_, tlPath))
                                tl6PlaceTrackList[1], tl6PlaceModelList[1] = self:PlaceModelToTimelineTrack(director, rolePrefabPath, TIMELINE_6_DEFINE.PREFAB, TIMELINE_6_DEFINE.ROLE_PLACE)
                                -- tl6PlaceTrackList[2], tl6PlaceModelList[2] = self:PlaceModelToTimelineTrack(director, scenePrefabPath, TIMELINE_6_DEFINE.PREFAB, TIMELINE_6_DEFINE.SCENE_PLACE, TIMELINE_6_DEFINE.SCENE_TRACK)
                                self:SetCurrentTimeLineData(TIMELINE_6_DEFINE, tl6PlaceTrackList, tl6PlaceModelList, tl6MarkerCallback)
                                -- 解决刚刚播放part4时，点击跳过产生的：角色坐标继承自part4刚开始前的初始坐标，导致继承到part6时的显示问题。
                                local modelPrefabObj = self:InitPrefabModel(rolePrefabPath)
                                modelPrefabObj.transform.localPosition = Vector3(0, 0, 0)
                                modelPrefabObj.transform.localRotation = Quaternion.Euler(0, 0, 0)
                            end,
                            -- finish callback
                            function(director)
                                self:SetTestLabelText(TIMELINE_6_DEFINE.NAME .. '_finish')
                                URPCameraController.alwaysShowSceneRT = true
                                showCardDisplayDialog(resultData)
                            end,
                            -- update callback
                            function(time, duration)
                                self:SetTestLabelText(TIMELINE_6_DEFINE.NAME .. string.format('_%0.3f/%0.3f', time, duration))
                                if not isShowingCardInfo then
                                    showCardInfoDialog(resultData)
                                end
                            end
                        )

                        lastTimelineDefine = TIMELINE_6_DEFINE
                        lastPlaceTrackList = tl6PlaceTrackList
                        lastPlaceModelList = tl6PlaceModelList
                        lastMarkerCallback = tl6MarkerCallback

                    else
                        lastTimelineDefine = TIMELINE_4_DEFINE
                        lastPlaceTrackList = tl4PlaceTrackList
                        lastPlaceModelList = tl4PlaceModelList
                        lastMarkerCallback = tl4MarkerCallback
                    end

                    if self._isActionSkipped or eachResultCardVo.rare == Constants.RareType.R then
                    else
                        if Constants.MODULE_SWITCH.SHARE then
                            Events.Broadcast(Constants.EventNames.GACHAPON_ANIM_RESULT_SHARE_ENABLE)
                        else
                            Events.Broadcast(Constants.EventNames.GACHAPON_ANIM_RESULT_CLOSE_ENABLE)
                        end

                        self:SetShare(true)

                        while self:GetShare() do
                            coroutine.yield()
                        end
                    end
                end

                ------------------------------------------------- [show introUI]
                if eachResultCardVo.rare ~= Constants.RareType.R  then
                    CARD_INFO_SHOW_TIME = 0.3
                else
                    CARD_INFO_SHOW_TIME = 0.2
                end

                -- while true do
                --     CoYield()
                -- end

                while isWaitingShowInfo do
                    CoYield()
                end
                CoYield(CARD_INFO_SHOW_TIME)

                isSkipToShowResult = false
                isShowingCardInfo  = false
            end

            if resultIndex == #self._displayResult then
                -- 最后关闭最后的tinmLine  ， 截屏 防止 界面切换出现黑屏
                URPCameraController.alwaysShowSceneRT = true
                self:CloseTimelineByDefine(lastTimelineDefine, lastPlaceTrackList, lastPlaceModelList, lastMarkerCallback)
            end
        until true
    end

    -- 全道具的结束表现
    if isAllGoods then
        -- load cat model
        local catPrefabPath = GachaponUtils.GetCatPrefabPath()
        if isNull(GachaponShared:GetModel(catPrefabPath)) then
            self:LoadPrefabModel(catPrefabPath, true)
        end

        -- play timeline goods
        local tlGoodsPlaceTrackList = {}
        local tlGoodsPlaceModelList = {}
        local tlGoodsMarkerCallback = nil
        local TIMELINE_GOODS_DEFINE = GachaponConstants.GachaponGuideAnimTLDefine.TIMELINE_GOODS
        self:SetTestLabelText(TIMELINE_GOODS_DEFINE.NAME .. '_relay')
        self:LoadAndPlayTimelineByDefine(TIMELINE_GOODS_DEFINE, false,
            -- loaded callback
            function()
                self:SetTestLabelText(TIMELINE_GOODS_DEFINE.NAME .. '_loaded')
                self:UpdateMainSceneLight(true)
                self:CloseTimelineByDefine(lastTimelineDefine, lastPlaceTrackList, lastPlaceModelList, lastMarkerCallback)
            end,
            -- init callback
            function(director, tlPath)
                URPCameraController.alwaysShowSceneRT = false
                self:SetTestLabelText(TIMELINE_GOODS_DEFINE.NAME .. '_initial')
                tlGoodsMarkerCallback   = GachaponUtils.AppendTimelineCustomNotify(director, Bind(self, self.OnTimelineMarkerNotifyHandler_, tlPath))
                tlGoodsPlaceTrackList[1], tlGoodsPlaceModelList[1] = self:PlaceModelToTimelineTrack(director, catPrefabPath, TIMELINE_GOODS_DEFINE.PREFAB, TIMELINE_GOODS_DEFINE.CAT_PLACE, TIMELINE_GOODS_DEFINE.GOODS_TRACK)
                self:SetCurrentTimeLineData(TIMELINE_GOODS_DEFINE, tlGoodsPlaceTrackList, tlGoodsPlaceModelList, tlGoodsMarkerCallback)
            end,
            -- finish callback
            function(director)
                self:SetTestLabelText(TIMELINE_GOODS_DEFINE.NAME .. '_finish')
                URPCameraController.alwaysShowSceneRT = true
            end,
            -- update callback
            function(time, duration, director)
                self:SetTestLabelText(TIMELINE_GOODS_DEFINE.NAME .. string.format('_%0.3f/%0.3f', time, duration))
            end
        )

        -- 最后关闭最后的tinmLine  ， 截屏 防止 界面切换出现黑屏
        URPCameraController.alwaysShowSceneRT = true
        self:CloseTimelineByDefine(TIMELINE_GOODS_DEFINE, tlGoodsPlaceTrackList, tlGoodsPlaceModelList, tlGoodsMarkerCallback)
    end

    -- while true do
    --     coroutine.yield()
    -- end

    ------------------------------------------------- [show result]
    self:ShowResult()
end

---@param prefabPath string
---@param isDelAnimator boolean
function GachaponGuideAnim:LoadPrefabModel(prefabPath, isDelAnimator)
    -- return CoStart(function()
        GachaponShared:LoadModel(prefabPath, nil, GachaponShared:GetLoadModelParentGo().transform)
        while not GachaponShared:GetModel(prefabPath) do
            CoYield()
        end
        self._loadedObjects[prefabPath] = true
        print('>> LoadPrefabModel', prefabPath)
        if isDelAnimator then
            ---@type UnityEngine.GameObject
            local prefabModel = GachaponShared:GetModel(prefabPath)
            ---@type UnityEngine.Animator
            local catAnimator = prefabModel and prefabModel:GetComponent(typeof(Animator)) or nil
            if not isNull(catAnimator) then
                catAnimator.runtimeAnimatorController = nil
            end
        end
    -- end)
end

---@param prefabPath string
---@return UnityEngine.GameObject | nil
function GachaponGuideAnim:InitPrefabModel(prefabPath)
    local go = GachaponShared:GetModel(prefabPath)
    if isNull(go) then
        return nil
    end

    if not CfUtils.IsActiveInHierarchy(go) then
        CfUtils.SetActive(go, true)
    end
    return go
end

---@param director UnityEngine.Playables.PlayableDirector
---@param modelPath string | UnityEngine.GameObject
---@param timelinePath string
---@param placePath string
---@param trackPath string
---@return UnityEngine.Object[], UnityEngine.GameObject
function GachaponGuideAnim:PlaceModelToTimelineTrack(director, modelPath, timelinePath, placePath, trackPath)
    local timelinePrefab = GachaponShared:GetModel(timelinePath)
    local parentObjTrans = timelinePrefab and (placePath and timelinePrefab.transform:Find(placePath) or timelinePrefab.transform) or nil
    local modelPrefabObj = type(modelPath) == 'string' and self:InitPrefabModel(modelPath) or modelPath
    if not isNull(modelPrefabObj) and not isNull(parentObjTrans) then
        -- reset parfabe parent
        local isPositionStays = not isNull(modelPrefabObj.transform.parent)
        modelPrefabObj.transform:SetParent(parentObjTrans, false)--isPositionStays == true)
        CfUtils.SetActive(modelPrefabObj, true)

        -- reset prefab transform
        if not isPositionStays then
            modelPrefabObj.transform.localPosition = Vector3(0, 0, 0)
            modelPrefabObj.transform.localRotation = Quaternion.Euler(0, 0, 0)
        end
    end

    -- place hand track
    local modelTrackSources = {}
    if director and trackPath and modelPrefabObj then
        modelTrackSources = GachaponUtils.BindTimeline(director, trackPath, modelPrefabObj)
    end
    return modelTrackSources, modelPrefabObj
end

--- 只关闭 对象身上绑定的timeline 和 和隐藏对象
---@param timelineDefine table
---@param trackBindList table[]
---@param trackmodelObjs UnityEngine.GameObject
---@param tlMarkerCallback CustomNotifyCallback
function GachaponGuideAnim:CloseRolePrefabTimeLineByDefine(timelineDefine, trackBindList, trackmodelObjs, tlMarkerCallback)
    if not timelineDefine then return end
    local timelinePrefab = GachaponShared:GetModel(timelineDefine.PREFAB)
    if not isNull(timelinePrefab) then

        ---@type UnityEngine.Playables.PlayableDirector
        local director = timelinePrefab.gameObject:GetComponent(typeof(PlayableDirector))
        if not isNull(director) then
            director:Stop()
            director:Evaluate()
            director.time = 0

            for _, modelObj in ipairs(trackmodelObjs or {}) do
                CfUtils.SetActive(modelObj, false)
            end

            for _, trackBind in ipairs(trackBindList or {}) do
                for _, bindKey in ipairs(trackBind) do
                    director:ClearGenericBinding(bindKey)
                end
            end

            if tlMarkerCallback then
                GachaponUtils.RemoveTimelineCustomNotify(director, tlMarkerCallback)
            end
        end

        --CfUtils.SetActive(timelinePrefab.gameObject, false)
    end
end


---@param timelineDefine table
---@param trackBindList table[]
---@param trackmodelObjs UnityEngine.GameObject
---@param tlMarkerCallback CustomNotifyCallback
function GachaponGuideAnim:CloseTimelineByDefine(timelineDefine, trackBindList, trackmodelObjs, tlMarkerCallback)
    if not timelineDefine then return end
    local timelinePrefab = GachaponShared:GetModel(timelineDefine.PREFAB)
    if not isNull(timelinePrefab) then

        ---@type UnityEngine.Playables.PlayableDirector
        local director = timelinePrefab.gameObject:GetComponent(typeof(PlayableDirector))
        if not isNull(director) then
            director:Stop()
            director:Evaluate()
            director.time = 0

            for _, modelObj in ipairs(trackmodelObjs or {}) do
                CfUtils.SetActive(modelObj, false)
            end

            for _, trackBind in ipairs(trackBindList or {}) do
                for _, bindKey in ipairs(trackBind) do
                    director:ClearGenericBinding(bindKey)
                end
            end

            if tlMarkerCallback then
                GachaponUtils.RemoveTimelineCustomNotify(director, tlMarkerCallback)
            end
        end

        CfUtils.SetActive(timelinePrefab.gameObject, false)
    end
end


