---@param timelineDefine table
---@param isCanSkip boolean
---@param loadedCB fun():void
---@param initCB fun(director:UnityEngine.Playables.PlayableDirector):void
---@param finishCB fun(director:UnityEngine.Playables.PlayableDirector):void
---@param updateCB fun(time:integer, duration:integer):void
function GachaponGuideAnim:LoadAndPlayTimelineByDefine(timelineDefine, isCanSkip, loadedCB, initCB, finishCB, updateCB)
    if not timelineDefine then return end
    self._isCanBeSkipped  = isCanSkip == true
    self._isActionSkipped = false
    self:LoadAndPlayTimeline(timelineDefine.PREFAB, timelineDefine.CAMERA, loadedCB, initCB, finishCB, updateCB)
end

---@param path string
---@param camPath string
---@param beforePlay fun():void
---@param initDirector fun(director:UnityEngine.Playables.PlayableDirector):void
---@param finishDirector fun(director:UnityEngine.Playables.PlayableDirector):void
---@param updateCallback fun(time:integer, duration:integer, director:UnityEngine.Playables.PlayableDirector):void
---@param waitTime number
function GachaponGuideAnim:LoadAndPlayTimeline(path, camPath, beforePlay, initDirector, finishDirector, updateCallback, waitTime)
    GachaponShared:LoadModel(path, nil, GachaponShared:GetLoadModelParentGo().transform)
    while not GachaponShared:GetModel(path) do
        CoYield()
    end

    if beforePlay ~= nil then
        beforePlay()
    end

    local go = GachaponShared:GetModel(path)

    if not isNull(go) then
        ---@type UnityEngine.Playables.PlayableDirector
        local director = go.gameObject:GetComponent(typeof(PlayableDirector))

        -- local cameraComp = go:GetComponentInChildren(typeof(Camera))
        local originCam = go.transform:Find(camPath).gameObject
        ---@type UnityEngine.Camera
        local cameraComp = originCam.gameObject:GetComponent(typeof(Camera))
        local cameraData = CameraExtensions.GetUniversalAdditionalCameraData(cameraComp)
        cameraData.cameraStack:Clear()

        CfUtils.SetActive(URPCameraController.mainCamera, false)
        URPCameraController:InitCameraStack(cameraComp)

        if self.cullingMaskMap[path] then
            cameraComp.cullingMask = self.cullingMaskMap[path].origin
        end
        self.cullingMaskMap[path] = {
            camera = cameraComp,
            origin = cameraComp.cullingMask,
            hidden = CfUtils.LayerMaskRemoves(cameraComp.cullingMask, {"scene", "scene_no_reflection"}),
        }

        if initDirector ~= nil then
            initDirector(director, path)
        end
        CfUtils.SetActive(go.gameObject, true)
        
        self._loadedTimelines[path] = true
        print('>> TimelineLoaded', path)
        
        --这边等一帧 criware轨的初始化
        -- CoYield()--不内嵌视频了，所以不用了。而且哪怕要等也不能写在这里，因为这会导致全部tl都顿一帧
        director.time = 0
        director:Play()

        if waitTime == nil then
            waitTime = math.floor(director.duration * 1000) / 1000
        end
        self._isWaitForAction = true
        -- CoYield(waitTime)
        local endTime = GetTimeByMillisecond() + waitTime
        while true do
            if isNull(director) or GetTimeByMillisecond() >= endTime then
                break
            else
                if self._isWaitForAction then
                    if updateCallback then
                        updateCallback(director.time, waitTime, director)
                    end
                    coroutine.yield()
                else
                    -- 如果是点击跳过，则跳到最后一帧做一次刷新
                    -- director.time = director.duration
                    break
                end
            end
        end
        self._isWaitForAction = false

        print('>> TimelineFinish', path)
        -- director:Stop()  -- 视频stop时会黑屏，导致衔接后面部分会出现褐色一闪的情况，所以这里不停止
        if finishDirector ~= nil and not isNull(director) then
            finishDirector(director)
        end
    end
end

