---@return integer
function GachaponGuideAnim:GetTopRareIndex()
    local statisticData = checkTable(self._statistic[self._topRare])
    local cardIndexes   = checkTable(statisticData.cardIndexes)
    local topRareIndex  = 1
    if #cardIndexes > 0 then
        if statisticData.cnt == 1 then
            topRareIndex = checkInt(cardIndexes[1])
        else
            local rIndex = math.random(1, #cardIndexes)
            topRareIndex = checkInt(cardIndexes[rIndex])
        end
    end
    return topRareIndex
end

---@param cardRare integer
---@return GachaponGuideAnimRateDefine
function GachaponGuideAnim:GetTimelineRateDefineByCardRare(cardRare)
    local allAnimRateDefine = GachaponConstants.GachaponGuideAnimRateDefine[checkInt(cardRare)]
    if allAnimRateDefine then
        local totalRate = 0
        for _, define in ipairs(allAnimRateDefine) do
            totalRate = totalRate + checkInt(define.rareRate)
        end

        local countRate  = 0
        local targetIdx  = 0
        local targetRate = math.random(1, totalRate)
        for defIndex, define in ipairs(allAnimRateDefine) do
            countRate = countRate + checkInt(define.rareRate)
            if countRate >= targetRate then
                targetIdx = defIndex
                break
            end
        end
        return allAnimRateDefine[targetIdx]
    end
end


---@return SceneInstance
function GachaponGuideAnim:GetSceneInstance()
    local sceneSettingId = GachaponConstants.GachaponGuideAnimSceneDefine.SCENE_ID
    local sceneInstance = GachaponShared:GetAppendedScene(sceneSettingId)
    return sceneInstance
end


---@param isVisible boolean
function GachaponGuideAnim:UpdateSceneStatus(isVisible)
    local sceneInstance = self:GetSceneInstance()
    if sceneInstance == nil then return end
    if isVisible then
        sceneInstance:Enable()
    else
        sceneInstance:Disable()
    end

    -- appear scene element
    for _, appearData in ipairs(GachaponConstants.GachaponGuideAnimSceneDefine.APPEARS or {}) do
        local nodeGo = sceneInstance:GetSceneElement(appearData.path)
        if not isNull(nodeGo) then
            CfUtils.SetActive(nodeGo, appearData.state == true)
        end
    end

    CfUtils.SetActive(GachaponShared:GetLoadModelParentGo(), true)
end


---@param isVisible boolean
function GachaponGuideAnim:UpdateMainSceneStatus(isVisible)
    local sceneInstance = self:GetSceneInstance()
    if sceneInstance == nil then return end
    for _, appearData in ipairs(GachaponConstants.GachaponGuideAnimSceneDefine.APPEARS or {}) do
        local nodeGo = sceneInstance:GetSceneElement(appearData.path)
        if not isNull(nodeGo) then
            CfUtils.SetActive(nodeGo, isVisible)
        end
    end
end


---@param isVisible boolean
function GachaponGuideAnim:UpdateMainSceneLight(isVisible)
    local sceneInstance = self:GetSceneInstance()
    if sceneInstance == nil then return end
    local sceneLightGo = sceneInstance:GetSceneElement(GachaponConstants.GachaponGuideAnimSceneDefine.LIGHT)
    CfUtils.SetActive(sceneLightGo, isVisible)
end


---@param tlPath string
---@param isVisible boolean
function GachaponGuideAnim:UpdateTimelineCameraCullingMask(tlPath, isVisible)
    local cullingMaskData = self.cullingMaskMap and self.cullingMaskMap[tlPath] or nil
    if cullingMaskData and cullingMaskData.camera then
        cullingMaskData.camera.cullingMask = isVisible and cullingMaskData.origin or cullingMaskData.hidden
    end
end


---@param tlPath string
---@param origin UnityEngine.Playables.Playable
---@param notification Markers.UIActiveMarker
---@param context System.Object
function GachaponGuideAnim:OnTimelineMarkerNotifyHandler_(tlPath, origin, notification, context)
    logs('>> MarkerNotify', tlPath, notification.time, notification.State)
    if notification:GetType() == typeof(CS.Markers.UIActiveMarker) then
        self:UpdateTimelineCameraCullingMask(tlPath, notification.State)
    end
end


function GachaponGuideAnim:SetTestLabelText(text)
    if not self.testLabelTxt then return end
    CfUtils.FillText(self.testLabelTxt, '> '..tostring(text))
    -- logs('[Gachapon.log]', tostring(text))
end


---@param tlRareDefines GachaponGuideAnimRateDefine
---@param displayResult table
---@return string
function GachaponGuideAnim:GetBeadPrefabPath(tlRareDefines, displayResult)
    local beadPrefabPath = nil
    -- 天上卡牌的球
    if GachaponUtils.IsCardGoods(displayResult.goodsId) then
        beadPrefabPath = GachaponConstants.GachaponGuideAnimBeadPath[tlRareDefines.baseRare]
        if GachaponUtils.IsOverseaLightDarkType(self._pool.poolType) then
            beadPrefabPath = GachaponConstants.GachaponGuideAnimLightDarkBeadPath[tlRareDefines.baseRare]
        end
    -- 天上道具的球
    else
        beadPrefabPath = GachaponConstants.GachaponGuideAnimGoodsBeadPath
        if GachaponUtils.IsOverseaLightDarkType(self._pool.poolType) then
            beadPrefabPath = GachaponConstants.GachaponGuideAnimLightDarkGoodsBeadPath
        end
    end
    return beadPrefabPath
end


return GachaponGuideAnim
